def secret(name, default=None):
    try:
        return st.secrets.get(name, default)
    except (FileNotFoundError, st.errors.StreamlitSecretNotFoundError):
        return default

def connection():
    url = secret('DATABASE_URL', '')
    if url:
        import psycopg
        return psycopg.connect(url, connect_timeout=10)
    if secret('STORAGE_MODE') == 'codespaces_atelier':
        folder = Path.home() / '.enquete_benin'
        folder.mkdir(exist_ok=True)
        con = sqlite3.connect(folder / 'reponses.sqlite3', timeout=20)
        con.execute('PRAGMA journal_mode=WAL')
        return con
    raise RuntimeError('Stockage non configuré')

def db_action(action, response=None, campaign=None):
    con = connection()
    pg = bool(secret('DATABASE_URL', ''))
    marker = '%s' if pg else '?'
    try:
        cur = con.cursor()
        cur.execute('''CREATE TABLE IF NOT EXISTS benin_reponses (
            response_id TEXT PRIMARY KEY, campaign TEXT NOT NULL,
            created_at TEXT NOT NULL, agent TEXT NOT NULL,
            entity_id TEXT NOT NULL, payload TEXT NOT NULL)''')
        if action == 'insert':
            cur.execute('INSERT INTO benin_reponses VALUES (' + ','.join([marker]*6) +
                ') ON CONFLICT (response_id) DO NOTHING', (
                response['response_id'], response['campagne'], response['horodatage_utc'],
                response['enqueteur'], response['organisme_id'],
                json.dumps(response, ensure_ascii=False)))
            inserted = cur.rowcount == 1
            con.commit()
            return inserted
        cur.execute('SELECT payload FROM benin_reponses WHERE campaign=' + marker +
                    ' ORDER BY created_at DESC', (campaign,))
        rows = [json.loads(x[0]) for x in cur.fetchall()]
        con.commit()
        return rows
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()

def authorized(role):
    return st.session_state.get('role') == role

def login():
    with st.form('connexion'):
        role = st.selectbox('Accès', ['Enquêteur', 'Superviseur'])
        code = st.text_input('Code d’accès', type='password')
        submit = st.form_submit_button('Ouvrir mon espace')
    if submit:
        name = 'SUPERVISOR_PASSWORD' if role == 'Superviseur' else 'COLLECTOR_PASSWORD'
        expected = secret(name, '')
        if expected and hmac.compare_digest(code.encode(), str(expected).encode()):
            st.session_state.role = role
            st.rerun()
        else:
            st.error('Code incorrect ou accès non configuré.')

def collector(registry, campaign):
    st.header('Questionnaire — pratiques de gestion des données')
    st.caption('Version 1 • Un entretien par organisme et par campagne. Exercice pédagogique ; aucune conclusion d’audit automatique.')
    categories = ['Toutes'] + sorted(registry['categorie'].unique().tolist())
    category = st.selectbox('Filtrer les organismes', categories)
    choices = registry if category == 'Toutes' else registry[registry.categorie == category]
    eid = st.selectbox('1. Organisme enquêté', choices['id'].tolist(),
        format_func=lambda i: i + ' — ' + registry.set_index('id').loc[i, 'nom'], index=None)
    if eid is None:
        st.info('Sélectionnez un organisme pour commencer.')
        return
    entity = registry.set_index('id').loc[eid]
    st.caption('Catégorie : ' + entity['categorie'] + ' • Source : ' + entity['source'] +
               ' • Actualité : ' + entity['actualite'] + ' • Assujettissement à confirmer.')
    st.session_state.setdefault('response_id', str(uuid.uuid4()))
    if st.session_state.get('last_receipt'):
        st.success('Dernier enregistrement confirmé : ' + st.session_state.last_receipt)
    with st.form('questionnaire_' + st.session_state.response_id, clear_on_submit=False):
        agent = st.text_input('2. Identifiant de l’enquêteur (ex. E01)', max_chars=40)
        interview_date = st.date_input('3. Date de collecte', date.today(), max_value=date.today())
        mode = st.selectbox('4. Mode de collecte', ['Face à face', 'Téléphone', 'Internet / visioconférence', 'Examen documentaire'])
        respondent = st.selectbox('5. Fonction de la personne interrogée',
            ['Responsable administratif', 'Responsable financier', 'Responsable suivi-évaluation', 'Responsable informatique / données', 'Autre fonction'])
        ns = ['Non renseigné', 'Oui', 'Non', 'Ne sait pas']
        database = st.selectbox('6. L’organisme dispose-t-il d’une base de données structurée ?', ns)
        tools = st.multiselect('7. Quels outils sont utilisés ?', ['Excel', 'Logiciel métier', 'Base SQL', 'Plateforme de collecte', 'Registres papier', 'Autre'])
        procedure = st.selectbox('8. Existe-t-il une procédure écrite de collecte et de validation ?', ns)
        frequency = st.selectbox('9. À quelle fréquence les données sont-elles actualisées ?',
            ['Non renseigné', 'Chaque jour', 'Chaque semaine', 'Chaque mois', 'Chaque trimestre', 'Chaque année', 'À la demande', 'Ne sait pas'])
        quality = st.multiselect('10. Quels contrôles sont effectivement réalisés ?',
            ['Complétude', 'Doublons', 'Cohérence', 'Rapprochement avec pièces justificatives', 'Validation par un responsable', 'Aucun contrôle déclaré', 'Ne sait pas'])
        backup = st.selectbox('11. Existe-t-il une sauvegarde régulière ?', ns)
        access = st.selectbox('12. Les droits d’accès sont-ils définis par fonction ?', ns)
        indicator = st.selectbox('13. Les données alimentent-elles des indicateurs de suivi-évaluation ?', ns)
        evidence = st.selectbox('14. Quel est le niveau de preuve disponible pour cet entretien ?',
            ['Déclaration seule', 'Document consulté', 'Observation directe', 'Déclaration et document', 'Non vérifié'])
        difficulty = st.text_area('15. Quelle est la principale difficulté rencontrée ?', max_chars=2000)
        improvement = st.text_area('16. Quelle amélioration prioritaire proposez-vous ?', max_chars=2000)
        consent = st.checkbox('La personne a été informée de l’objectif pédagogique et accepte de répondre. Aucun nom, dossier confidentiel ou donnée personnelle ne figure dans mes commentaires.')
        submit = st.form_submit_button('Enregistrer la réponse', type='primary')
    if submit:
        issues = []
        if not agent.strip(): issues.append('Renseignez l’identifiant de l’enquêteur.')
        if not consent: issues.append('Confirmez l’information et l’accord du répondant.')
        if 'Non renseigné' in [database, procedure, frequency, backup, access, indicator]:
            issues.append('Complétez les questions obligatoires ; « Ne sait pas » est accepté.')
        if 'Aucun contrôle déclaré' in quality and len(quality)>1:
            issues.append('« Aucun contrôle déclaré » doit être sélectionné seul.')
        if 'Ne sait pas' in quality and len(quality)>1:
            issues.append('« Ne sait pas » doit être sélectionné seul pour les contrôles.')
        if issues:
            for issue in issues: st.error(issue)
            return
        response = dict(response_id=st.session_state.response_id, campagne=campaign,
            version_questionnaire='1', horodatage_utc=datetime.now(timezone.utc).isoformat(),
            date_collecte=interview_date.isoformat(), enqueteur=agent.strip(), organisme_id=eid,
            organisme=entity['nom'], categorie=entity['categorie'], departement=entity['departement'],
            mode_collecte=mode, fonction_repondant=respondent, base_structuree=database,
            outils=tools, procedure_validation=procedure, frequence_actualisation=frequency,
            controles=quality, sauvegarde=backup, droits_acces=access, indicateurs=indicator,
            preuve=evidence, difficulte=difficulty.strip(), amelioration=improvement.strip(), accord=True)
        try:
            db_action('insert', response=response)
        except Exception:
            st.error('Enregistrement non confirmé. Vos réponses restent affichées ; réessayez sans fermer la page.')
            return
        st.session_state.last_receipt = response['response_id']
        # Le même identifiant garantit qu’un double envoi de ce formulaire n’ajoute pas deux réponses.
        st.success('Réponse enregistrée. Référence : ' + response['response_id'])
    if st.button('Commencer un nouvel entretien'):
        st.session_state.response_id = str(uuid.uuid4())
        for key in list(st.session_state):
            if key not in ['role', 'response_id', 'last_receipt']: del st.session_state[key]
        st.rerun()

@st.fragment(run_every='10s')
def dashboard(registry, campaign):
    if not authorized('Superviseur'): return
    st.header('Supervision de la collecte')
    st.caption('Actualisation toutes les 10 secondes pendant que cette page est ouverte • Campagne : ' + campaign)
    try:
        rows = db_action('read', campaign=campaign)
    except Exception:
        st.error('La base partagée est momentanément inaccessible. Aucun résultat actualisé ne peut être confirmé.')
        return
    df = pd.DataFrame(rows)
    a,b,c=st.columns(3)
    a.metric('Entretiens enregistrés', len(df))
    b.metric('Organismes distincts', df.organisme_id.nunique() if len(df) else 0)
    c.metric('Enquêteurs actifs', df.enqueteur.nunique() if len(df) else 0)
    st.caption('Registre de référence : ' + str(len(registry)) + ' fiches. Il ne constitue pas un N de campagne validé ; aucun taux de couverture n’est calculé automatiquement.')
    st.caption('Dernière lecture réussie (UTC) : ' + datetime.now(timezone.utc).strftime('%H:%M:%S'))
    if df.empty:
        st.info('Aucune réponse enregistrée pour cette campagne. Les premières réponses apparaîtront ici.')
        return
    cats = st.multiselect('Catégories à afficher', sorted(df.categorie.unique()), key='dashboard_categories')
    view = df[df.categorie.isin(cats)] if cats else df
    if view.empty:
        st.info('Aucune réponse pour ces catégories.')
        return
    a,b=st.columns(2)
    with a:
        st.subheader('Entretiens par catégorie')
        st.bar_chart(view.categorie.value_counts())
    with b:
        st.subheader('Base structurée déclarée')
        st.bar_chart(view.base_structuree.value_counts())
    st.subheader('Contrôles de collecte')
    duplicates = view.groupby(['organisme_id']).size()
    if (duplicates>1).any():
        st.warning(str((duplicates>1).sum()) + ' organisme(s) ont plusieurs entretiens dans cette campagne : vérifier s’il s’agit d’entretiens complémentaires ou de doublons.')
    st.dataframe(view[['horodatage_utc','enqueteur','organisme','categorie','base_structuree','preuve']], hide_index=True, use_container_width=True)
    st.subheader('Difficultés et propositions')
    st.dataframe(view[['organisme','difficulte','amelioration']], hide_index=True, use_container_width=True)
    export = view.copy()
    for col in ['outils','controles']: export[col] = export[col].apply(lambda x: '; '.join(x))
    # Neutraliser les formules lors de l’export des réponses libres vers Excel.
    for col in export.select_dtypes(include='object'):
        export[col] = export[col].map(lambda x: "'"+x if isinstance(x,str) and x.lstrip().startswith(('=','+','-','@')) else x)
    buf = BytesIO()
    with pd.ExcelWriter(buf, engine='openpyxl') as writer:
        export.to_excel(writer, sheet_name='REPONSES', index=False)
    st.download_button('Télécharger les réponses en Excel', buf.getvalue(), 'reponses_enquete_benin.xlsx',
        mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    st.caption('Les déclarations restent à confronter à des preuves. Aucun score de conformité ni conclusion d’audit n’est déduit de ces réponses.')

def main():
    st.set_page_config(page_title='Collecte — Cour des comptes du Bénin', page_icon='📋', layout='wide')
    st.title('Collecte et supervision des données')
    st.caption('Atelier de formation — Cour des comptes du Bénin')
    if not secret('COLLECTOR_PASSWORD') or not secret('SUPERVISOR_PASSWORD'):
        st.info('Application prête. Le formateur doit configurer les deux codes d’accès dans les secrets avant de commencer la collecte.')
        st.stop()
    if hmac.compare_digest(str(secret('COLLECTOR_PASSWORD')).encode(), str(secret('SUPERVISOR_PASSWORD')).encode()):
        st.error('Les codes enquêteur et superviseur doivent être différents.')
        st.stop()
    if not secret('DATABASE_URL') and secret('STORAGE_MODE') != 'codespaces_atelier':
        st.info('Connectez une base PostgreSQL durable dans DATABASE_URL pour enregistrer et partager les réponses.')
        st.stop()
    if not secret('DATABASE_URL'):
        st.warning('Mode atelier Codespaces : stockage dans cette machine. Exportez les résultats ; ce mode ne convient pas au stockage durable sur Streamlit Community Cloud.')
    registry = pd.DataFrame(REGISTRY_DATA)
    campaign = str(secret('CAMPAIGN_ID', 'ATELIER-BENIN-2026-10-07'))
    if not st.session_state.get('role'):
        login()
        return
    with st.sidebar:
        st.write('Espace : ' + st.session_state.role)
        st.write('Campagne : ' + campaign)
        if st.button('Se déconnecter'):
            st.session_state.clear()
            st.rerun()
    if authorized('Superviseur'): dashboard(registry, campaign)
    elif authorized('Enquêteur'): collector(registry, campaign)

if __name__ == '__main__':
    main()
